using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.Hosting;
using Aspire.Hosting.Testing;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalSetup
{
    private static DistributedApplication? _app;
    private static IChatClient? _chatClient;
    private static ReportingConfiguration? _reportingConfiguration;

    public static IChatClient ChatClient =>
        _chatClient ?? throw new InvalidOperationException("Call InitializeAsync first.");

    public static ReportingConfiguration ReportingConfiguration =>
        _reportingConfiguration ?? throw new InvalidOperationException("Call InitializeAsync first.");

    [AssemblyInitialize]
    public static async Task InitializeAsync(TestContext context)
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await builder.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.CreateHttpClient("chat") is { } _
            ? _app.Services.GetRequiredService<IChatClient>()
            : throw new InvalidOperationException("Could not resolve chat client.");

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task CleanupAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(EvalSetup).Assembly.Location)!,
            "eval-results");

        var storage = new DiskBasedReportingStorage(path);

        return new ReportingConfiguration(
            storage,
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ]);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    [TestMethod]
    public async Task AnswersGreeting()
    {
        await using var scenario = await EvalSetup.ReportingConfiguration
            .CreateScenarioRunAsync(
                scenarioName: nameof(AnswersGreeting));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await EvalSetup.ChatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        // Verify we got a non-empty response
        Assert.IsFalse(
            string.IsNullOrWhiteSpace(response.Text),
            "Expected a non-empty response from the chat model.");
    }

    [TestMethod]
    public async Task AnswersFactualQuestion()
    {
        await using var scenario = await EvalSetup.ReportingConfiguration
            .CreateScenarioRunAsync(
                scenarioName: nameof(AnswersFactualQuestion));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await EvalSetup.ChatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        Assert.IsTrue(
            response.Text.Contains("Paris", StringComparison.OrdinalIgnoreCase),
            "Expected the response to mention Paris.");
    }

    [TestMethod]
    public async Task FollowsSystemPrompt()
    {
        await using var scenario = await EvalSetup.ReportingConfiguration
            .CreateScenarioRunAsync(
                scenarioName: nameof(FollowsSystemPrompt));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that always responds in exactly one sentence."),
            new(ChatRole.User, "Explain what .NET is.")
        };

        var response = await EvalSetup.ChatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(response.Text),
            "Expected a non-empty response from the chat model.");
    }
}

