using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalSetup
{
    private static IChatClient? _chatClient;
    private static ReportingConfiguration? _reportingConfiguration;

    public static IChatClient ChatClient =>
        _chatClient ?? throw new InvalidOperationException("Call Initialize first.");

    public static ReportingConfiguration ReportingConfiguration =>
        _reportingConfiguration ?? throw new InvalidOperationException("Call Initialize first.");

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        _chatClient = CreateChatClient();
        _reportingConfiguration = CreateReportingConfiguration();
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException(
                "Set the AZURE_OPENAI_ENDPOINT environment variable.");

        var deploymentName = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "chat";

        var client = new AzureOpenAIClient(
            new Uri(endpoint),
            new DefaultAzureCredential());

        return client.GetChatClient(deploymentName).AsIChatClient();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(EvalSetup).Assembly.Location)!,
            "eval-results");

        var chatConfig = new ChatConfiguration(ChatClient);

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: path,
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: chatConfig);
    }
}

